  "stack": "'use client';\n\nimport React from 'react';\nimport { Button, Divider, InputNumber, message, Space, Switch } from '@ceebee/ui/client';\n\nconst App: React.FC = () => {\n  const [enabled, setEnabled] = React.useState(true);\n  const [threshold, setThreshold] = React.useState(3);\n  const indexRef = React.useRef(0);\n  const [messageApi, contextHolder] = message.useMessage({\n    stack: enabled\n      ? {\n          threshold,\n        }\n      : false,\n  });\n\n  const openMessage = () => {\n    indexRef.current += 1;\n    const isOdd = indexRef.current % 2 === 1;\n\n    messageApi.open({\n      type: 'info',\n      content: isOdd\n        ? `Message ${indexRef.current}: This is a stacked message.`\n        : `Message ${indexRef.current}: This is a slightly longer stacked message.`,\n      duration: 0,\n    });\n  };\n\n  return (\n    <>\n      {contextHolder}\n      <Space size=\"large\">\n        <Space style={{ width: '100%' }}>\n          <span>Enabled: </span>\n          <Switch\n            aria-label=\"Enable message stack\"\n            checked={enabled}\n            onChange={(v) => setEnabled(v)}\n          />\n        </Space>\n        <Space style={{ width: '100%' }}>\n          <span>Threshold: </span>\n          <InputNumber\n            aria-label=\"Stack threshold\"\n            disabled={!enabled}\n            value={threshold}\n            step={1}\n            min={1}\n            max={10}\n            onChange={(v) => setThreshold(v ?? 1)}\n          />\n        </Space>\n      </Space>\n      <Divider />\n      <Space>\n        <Button type=\"primary\" onClick={openMessage}>\n          Open the message box\n        </Button>\n        <Button onClick={() => messageApi.destroy()}>Destroy all</Button>\n      </Space>\n    </>\n  );\n};\n\nexport default App;\n",
